1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;
8	
9	/**
10	 * Household duplicate-detection step of {@code POST /api/owners}. Runs after {@link AssignHousehold}
11	 * (so the new owner's deterministic {@code householdId} is set) and before
12	 * {@link CheckOwnerIdentityUnique}.
13	 *
14	 * <p>Because a household is now keyed on {@code (lastName, postcode)}, two owners sharing a last name
15	 * and postcode are the same household. A second such owner is rejected with a 409 via
16	 * {@link OwnerHouseholdDuplicateException} — <em>unless</em> the request declares the shared household
17	 * via {@code sharesHousehold}, in which case the new owner is accepted as a declared household member.
18	 * The {@code sharesHousehold} flag only bypasses this block; it no longer creates the household link,
19	 * which is derived automatically from the computed {@code householdId}.
20	 *
21	 * <p>An owner with no postcode has a {@code null} {@code householdId} (no household to key on) and so is
22	 * never a household duplicate. The new owner is still unsaved, so it is not among the owners iterated
23	 * here and cannot match itself.
24	 */
25	public class CheckOwnerHouseholdUnique {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws OwnerHouseholdDuplicateException {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return; // declared household member: bypass the duplicate block
31	        }
32	        String householdId = owner.getHouseholdId();
33	        if (householdId == null) {
34	            return; // no postcode, so no household to collide with
35	        }
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (householdId.equals(existing.getHouseholdId())) {
38	                throw new OwnerHouseholdDuplicateException(householdId);
39	            }
40	        }
41	    }
42	}
