7	 * The single definition of how an owner's {@code address} is normalized. Applied whenever an owner is
8	 * created (see {@link ValidateOwner}, which stores and returns the normalized value), so the stored,
9	 * abbreviation-expanded address is consistent.
10	 *
11	 * <p>Normalization: strip surrounding whitespace and collapse internal runs to a single space,
12	 * upper-case, then expand common abbreviations token-by-token ({@code ST}→{@code STREET},
13	 * {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). A value that is blank after this is normalized
14	 * to the empty string, which {@link ValidateOwner} treats as a missing required field.
15	 */
16	public final class OwnerAddress {
17	
18	    /** Whole-token abbreviation expansions, keyed by the upper-cased token. */
19	    private static final Map<String, String> ABBREVIATIONS = Map.of(
20	            "ST", "STREET",
21	            "RD", "ROAD",
22	            "AVE", "AVENUE");
23	
24	    private OwnerAddress() {
25	    }
26	
27	    public static String normalize(String value) {
28	        if (value == null) {
29	            return "";
30	        }
31	        String collapsed = value.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
32	        if (collapsed.isEmpty()) {
33	            return "";
34	        }
35	        String[] tokens = collapsed.split(" ");
36	        StringBuilder result = new StringBuilder(collapsed.length());
37	        for (int i = 0; i < tokens.length; i++) {
38	            if (i > 0) {
39	                result.append(' ');
40	            }
41	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
42	        }
43	        return result.toString();
44	    }
45	}
